seq = ""
with open("region.fasta") as f:
    for line in f:
        if line.startswith(">"): continue
        seq += line.strip()
comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
stops={"TAA","TAG","TGA"}

# stop codon density per 100 bp, across all 6 frames
for w in range(0,3000,100):
    win = seq[w:w+100]
    tot=0
    for strand, ss in (("+",win),("-",rc(win))):
        for frm in range(3):
            s2=ss[frm:]
            tot += sum(1 for i in range(0,len(s2)-2,3) if s2[i:i+3] in stops)
    gc = 100*sum(c in "GC" for c in win)/len(win)
    print(f"{w+1:5d} gc={gc:4.0f}%  stops_total={tot}  (max 6*34=204-ish expected for random)")

